def get_api_key():
    try:
        return (
            st.secrets.get("OPENAI_API_KEY", "")
            or os.environ.get("OPENAI_API_KEY", "")
        )
    except Exception:
        return os.environ.get(
            "OPENAI_API_KEY",
            "",
        )


client = OpenAI(
    api_key=get_api_key()
)


# -------------------------------------------------------------------
# Source database
# -------------------------------------------------------------------


@st.cache_data(show_spinner=False, ttl=300)
def load_sources():
    try:
        with open(
            "sources.json",
            "r",
            encoding="utf-8",
        ) as file:
            raw_sources = json.load(file)

        sources = []

        for source in raw_sources:
            title = (
                source.get(
                    "title",
                    "",
                ).strip()
            )

            parent_title = (
                source.get(
                    "parent_title",
                    title,
                ).strip()
            )

            url = (
                source.get(
                    "url",
                    "",
                ).strip()
            )

            source_type = (
                source.get(
                    "source_type",
                    "Approved source",
                ).strip()
            )

            text = (
                source.get(
                    "text",
                    "",
                ).strip()
            )

            if not title or not url or not text:
                continue

            sources.append({
                "title": title,
                "parent_title": parent_title,
                "url": url,
                "source_type": source_type,
                "chunk_number": source.get(
                    "chunk_number",
                    1,
                ),
                "chunk_count": source.get(
                    "chunk_count",
                    1,
                ),
                "text": text,
            })

        return sources

    except Exception:
        return []


# -------------------------------------------------------------------
# Retrieval-query normalisation
# -------------------------------------------------------------------


def normalise_retrieval_question(question):
    """
    Expand a small set of important BIONEXT/domain abbreviations and spelling
    variants before retrieval.

    This improves recall for short acronym queries such as "What is MCDA?"
    without changing the user's visible question or relaxing the evidence gate.
    """
    if not question:
        return question

    normalised = question.strip()
    lower = normalised.lower()

    full_mcda_pattern = (
        r"\bmulti[-\s]+criteria\s+decision\s+analysis\b"
    )

    if (
        re.search(r"\bmcda\b", lower)
        and not re.search(full_mcda_pattern, lower)
    ):
        normalised = re.sub(
            r"\bmcda\b",
            "multi-criteria decision analysis (MCDA)",
            normalised,
            flags=re.IGNORECASE,
        )

    normalised = re.sub(
        full_mcda_pattern,
        "multi-criteria decision analysis (MCDA)",
        normalised,
        flags=re.IGNORECASE,
    )

    return normalised


# -------------------------------------------------------------------
# Routing
# -------------------------------------------------------------------


def route_question(question):
    q = question.lower()

    # Explicit IPBES wording should override the generic phrase
    # "transformative change", because BIONEXT also uses that phrase.
    if any(
        term in q
        for term in [
            "ipbes",
            "transformative change assessment",
            "summary for policymakers",
            "chapter 1",
            "chapter 2",
            "chapter 3",
            "chapter 4",
            "chapter 5",
        ]
    ):
        return "IPBES and transformative change route"

    if any(
        term in q
        for term in [
            "decision",
            "mcda",
            "multi-criteria",
            "criteria",
            "trade-off",
            "tradeoff",
            "impact assessment",
            "stakeholder preferences",
            "sensitivity analysis",
        ]
    ):
        return "Decision-analysis route"

    if any(
        term in q
        for term in [
            "case study",
            "case studies",
            "case-study",
            "case-studies",
        ]
    ):
        return "BIONEXT case-studies route"

    if any(
        term in q
        for term in [
            "resource",
            "policy brief",
            "report",
            "deliverable",
            "publication",
            "output",
            "pdf",
            "fact sheet",
        ]
    ):
        return "BIONEXT resources route"

    if any(
        term in q
        for term in [
            "cordis",
            "grant",
            "funding",
            "eu project",
            "101059662",
        ]
    ):
        return "CORDIS project-information route"

    return "General BIONEXT route"


# -------------------------------------------------------------------
# Source classification and weighting
# -------------------------------------------------------------------


def is_bionext_source(source):
    source_type = source["source_type"].lower()
    return (
        "bionext" in source_type
        or "oppla bionext" in source_type
    )


def is_ipbes_source(source):
    return "ipbes" in source["source_type"].lower()


def is_cordis_source(source):
    return (
        "approved external source"
        in source["source_type"].lower()
        and "cordis" in source["parent_title"].lower()
    )


def source_priority_bonus(route, source):
    """
    Give BIONEXT sources a modest default advantage while still allowing
    route-specific external evidence to rise to the top when appropriate.
    """

    bonus = 0.0

    if is_bionext_source(source):
        bonus += BIONEXT_BASE_BONUS

    source_type = source["source_type"].lower()

    if route == "Decision-analysis route":
        if "decision-analysis" in source_type:
            bonus += 0.060
        elif is_bionext_source(source):
            bonus += 0.015

    elif route == "BIONEXT case-studies route":
        if "bionext case study" in source_type:
            bonus += 0.070
        elif is_bionext_source(source):
            bonus += 0.010

    elif route == "BIONEXT resources route":
        if "bionext resource page" in source_type:
            bonus += 0.055
        elif "bionext pdf" in source_type:
            bonus += 0.045
        elif is_bionext_source(source):
            bonus += 0.015

    elif route == "IPBES and transformative change route":
        if is_ipbes_source(source):
            bonus += 0.075
        elif is_bionext_source(source):
            bonus += 0.010

    elif route == "CORDIS project-information route":
        if is_cordis_source(source):
            bonus += 0.090
        elif is_bionext_source(source):
            bonus += 0.010

    return bonus


# -------------------------------------------------------------------
# Compact text used for semantic embeddings
# -------------------------------------------------------------------


def make_embedding_text(source):
    """
    Build a compact semantic representation of a source chunk.

    The complete chunk remains available for answer generation. Only the
    representation sent to the embeddings endpoint is shortened.
    """

    body = source["text"]

    if len(body) > EMBEDDING_TEXT_MAX_CHARS:
        head_chars = int(EMBEDDING_TEXT_MAX_CHARS * 0.72)
        tail_chars = EMBEDDING_TEXT_MAX_CHARS - head_chars

        body = (
            body[:head_chars]
            + "\n...\n"
            + body[-tail_chars:]
        )

    return (
        f"Title: {source['parent_title']}\n"
        f"Source type: {source['source_type']}\n"
        f"Text: {body}"
    )


# -------------------------------------------------------------------
# Embeddings
# -------------------------------------------------------------------


@st.cache_data(
    show_spinner=False,
    ttl=3600,
)
def create_source_embeddings(texts):
    """
    Create embeddings for retrieval chunks in safe batches.

    Each text supplied here is already compacted by make_embedding_text().
    Requests are also retried with exponential backoff if the API temporarily
    reports a rate-limit response.
    """

    if not texts:
        return []

    embeddings = []

    for start in range(
        0,
        len(texts),
        EMBEDDING_BATCH_SIZE,
    ):
        batch = texts[
            start:start + EMBEDDING_BATCH_SIZE
        ]

        last_error = None

        for attempt in range(EMBEDDING_MAX_RETRIES):
            try:
                response = client.embeddings.create(
                    model=EMBEDDING_MODEL,
                    input=batch,
                )

                ordered = sorted(
                    response.data,
                    key=lambda item: item.index,
                )

                embeddings.extend(
                    item.embedding
                    for item in ordered
                )

                last_error = None
                break

            except Exception as exc:
                last_error = exc

                message = str(exc).lower()

                if (
                    "429" not in message
                    and "rate" not in message
                    and "tpm" not in message
                ):
                    raise

                if attempt >= EMBEDDING_MAX_RETRIES - 1:
                    raise

                wait_seconds = (
                    EMBEDDING_RETRY_BASE_SECONDS
                    * (2 ** attempt)
                )

                time.sleep(wait_seconds)

        if last_error is not None:
            raise last_error

    return embeddings


def create_query_embedding(question):
    response = client.embeddings.create(
        model=EMBEDDING_MODEL,
        input=question,
    )

    return response.data[0].embedding


# -------------------------------------------------------------------
# Similarity
# -------------------------------------------------------------------


def cosine_similarity(vector_a, vector_b):
    dot_product = sum(
        a * b
        for a, b in zip(
            vector_a,
            vector_b,
        )
    )

    magnitude_a = math.sqrt(
        sum(
            value * value
            for value in vector_a
        )
    )

    magnitude_b = math.sqrt(
        sum(
            value * value
            for value in vector_b
        )
    )

    if magnitude_a == 0 or magnitude_b == 0:
        return 0.0

    return (
        dot_product
        / (magnitude_a * magnitude_b)
    )


def keyword_score(question, source):
    """
    Small lexical score used alongside semantic similarity.

    Embeddings do most of the retrieval work; lexical overlap helps with
    specific project terms, document names, acronyms and policy language.
    """

    words = re.findall(
        r"[a-zA-Z][a-zA-Z-]{2,}",
        question.lower(),
    )

    stop_words = {
        "what",
        "when",
        "where",
        "which",
        "about",
        "does",
        "from",
        "with",
        "that",
        "this",
        "there",
        "their",
        "your",
        "into",
        "have",
        "has",
        "how",
        "why",
        "who",
        "are",
        "was",
        "were",
        "tell",
        "give",
        "explain",
    }

    words = [
        word
        for word in words
        if word not in stop_words
    ]

    if not words:
        return 0.0

    title_text = source["parent_title"].lower()
    body_text = source["text"].lower()

    # Exact overlap in the source title is more informative than a match
    # buried somewhere in a long chunk.
    title_matches = sum(
        title_text.count(word)
        for word in words
    )

    body_matches = sum(
        body_text.count(word)
        for word in words
    )

    weighted_matches = (
        title_matches * 2.5
        + body_matches
    )

    return min(
        weighted_matches / max(len(words), 1),
        10,
    ) / 10


def _normalised_title_words(text):
    """
    Return useful lowercase tokens for matching short user references against
    BIONEXT case-study titles.

    Generic conversational words and generic project/case-study terms are
    removed so that a query such as "Tell me about Dartmoor" is matched on
    "dartmoor", rather than on uninformative words such as "tell" or "about".
    """
    words = re.findall(
        r"[a-z0-9][a-z0-9'-]*",
        text.lower().replace("&", " and "),
    )

    stop_words = {
        "a",
        "an",
        "and",
        "are",
        "about",
        "bionext",
        "can",
        "case",
        "cases",
        "could",
        "do",
        "does",
        "for",
        "from",
        "give",
        "how",
        "in",
        "is",
        "me",
        "of",
        "on",
        "project",
        "projects",
        "restoration",
        "study",
        "studies",
        "tell",
        "the",
        "this",
        "to",
        "what",
        "which",
        "with",
        "you",
    }

    return [
        word.strip("-'")
        for word in words
        if word.strip("-'")
        and word.strip("-'") not in stop_words
    ]


def case_study_title_match_score(question, source):
    """
    Score distinctive partial-title matches for approved BIONEXT case studies.

    This is intentionally restricted to the case-study source type. It helps
    natural shorthand such as "Dartmoor", "Carbon Landscape" or "100,000
    Trees" retrieve the corresponding case study without weakening retrieval
    for unrelated BIONEXT content.
    """
    source_type = source["source_type"].lower()

    # The case-study pages are currently stored as Oppla BIONEXT pages, so also
    # recognise them from their canonical URL path.
    source_url = (
        source.get("url")
        or source.get("source_url")
        or ""
    ).lower()

    is_case_study_source = (
        "bionext case study" in source_type
        or "/bionext/case-study/" in source_url
    )

    if not is_case_study_source:
        return 0.0

    query_words = _normalised_title_words(question)
    title_words = _normalised_title_words(source["parent_title"])

    if not query_words or not title_words:
        return 0.0

    query_set = set(query_words)
    title_set = set(title_words)
    matched = query_set.intersection(title_set)

    if not matched:
        return 0.0

    # A single distinctive title token such as "dartmoor" or "groasis" is
    # enough for a shorthand-title match. Numeric tokens alone are not.
    distinctive = [
        word
        for word in matched
        if not word.isdigit() and len(word) >= 4
    ]

    if not distinctive:
        return 0.0

    coverage = len(matched) / max(len(query_set), 1)

    # If all informative query tokens occur in the title, treat it as a strong
    # title match. This is intentionally a ranking hint, not a replacement for
    # semantic relevance.
    if coverage >= 1.0:
        return 0.120

    if coverage >= 0.67:
        return 0.085

    if coverage >= 0.50:
        return 0.060

    return 0.035


def concept_match_bonus(question, source):
    """
    Add a small exact-concept bonus for important domain terms whose short
    forms can otherwise be weak semantic queries.

    The bonus does not create evidence. It only helps chunks that actually
    contain the requested concept rise within the already approved corpus.
    """
    q = question.lower().replace("-", " ")
    title = source["parent_title"].lower().replace("-", " ")
    body = source["text"].lower().replace("-", " ")
    source_text = title + "\n" + body

    asks_about_mcda = (
        re.search(r"\bmcda\b", q) is not None
        or "multi criteria decision analysis" in q
    )

    if asks_about_mcda:
        contains_mcda = (
            re.search(r"\bmcda\b", source_text) is not None
            or "multi criteria decision analysis" in source_text
        )

        if contains_mcda:
            return 0.080

        if "decision analysis: the basics" in title:
            return 0.060

    return 0.0


# -------------------------------------------------------------------
# Retrieval
# -------------------------------------------------------------------


def retrieve_sources(
    question,
    sources,
    allowed_source_types,
):
    route = route_question(question)

    filtered_sources = [
        source
        for source in sources
        if source["source_type"]
        in allowed_source_types
    ]

    if not filtered_sources:
        return [], route

    texts = [
        make_embedding_text(source)
        for source in filtered_sources
    ]

    source_embeddings = (
        create_source_embeddings(texts)
    )

    question_embedding = (
        create_query_embedding(question)
    )

    scored = []

    for source, embedding in zip(
        filtered_sources,
        source_embeddings,
    ):
        semantic = cosine_similarity(
            question_embedding,
            embedding,
        )

        lexical = keyword_score(
            question,
            source,
        )

        priority = source_priority_bonus(
            route,
            source,
        )

        concept_bonus = concept_match_bonus(
            question,
            source,
        )

        title_match_bonus = case_study_title_match_score(
            question,
            source,
        )

        # Semantic relevance remains dominant. Source/concept/title bonuses are
        # deliberately small and only help clearly matching approved evidence
        # rise above more generic material.
        combined_score = (
            semantic * 0.86
            + lexical * 0.14
            + priority
            + concept_bonus
            + title_match_bonus
        )

        scored.append({
            **source,
            "semantic_score": semantic,
            "keyword_score": lexical,
            "priority_bonus": priority,
            "concept_bonus": concept_bonus,
            "title_match_bonus": title_match_bonus,
            "retrieval_score": combined_score,
        })

    scored.sort(
        key=lambda item: item[
            "retrieval_score"
        ],
        reverse=True,
    )

    selected = []
    document_counts = {}
    external_count = 0

    if route == "IPBES and transformative change route":
        external_limit = IPBES_ROUTE_MAX_EXTERNAL_CHUNKS
    elif route == "CORDIS project-information route":
        external_limit = TOP_CHUNKS
    else:
        external_limit = DEFAULT_MAX_EXTERNAL_CHUNKS

    for source in scored:
        document_key = (
            source["parent_title"],
            source["url"],
        )

        count = document_counts.get(
            document_key,
            0,
        )

        if count >= MAX_CHUNKS_PER_DOCUMENT:
            continue

        external = not is_bionext_source(source)

        if external and external_count >= external_limit:
            continue

        selected.append(source)

        document_counts[
            document_key
        ] = count + 1

        if external:
            external_count += 1

        if len(selected) >= TOP_CHUNKS:
            break

    return selected, route


# -------------------------------------------------------------------
# Group retrieved chunks into citation sources
# -------------------------------------------------------------------


def group_retrieved_sources(retrieved):
    grouped = {}

    for source in retrieved:
        key = (
            source["parent_title"],
            source["url"],
        )

        if key not in grouped:
            grouped[key] = {
                "title": source["parent_title"],
                "url": source["url"],
                "source_type": source[
                    "source_type"
                ],
                "chunks": [],
                "best_score": source[
                    "retrieval_score"
                ],
            }

        grouped[key]["chunks"].append(
            source
        )

        grouped[key]["best_score"] = max(
            grouped[key]["best_score"],
            source["retrieval_score"],
        )

    groups = list(
        grouped.values()
    )

    groups.sort(
        key=lambda item: item[
            "best_score"
        ],
        reverse=True,
    )

    return groups


# -------------------------------------------------------------------
# Prompt context
# -------------------------------------------------------------------


def make_context(groups):
    """
    Build a compact evidence context for the answer model.

    Retrieved chunks can be very large, particularly for long reports.
    This function enforces hard limits on individual passages and on the
    complete prompt context.
    """

    blocks = []
    total_chars = 0

    for source_number, group in enumerate(
        groups[:MAX_SOURCES_IN_PROMPT],
        start=1,
    ):
        passages = []

        for chunk in group["chunks"]:
            text = chunk["text"]

            if len(text) > MAX_CHARS_PER_CHUNK:
                text = (
                    text[:MAX_CHARS_PER_CHUNK]
                    + "\n\n[Text truncated]"
                )

            chunk_label = (
                f"Chunk {chunk['chunk_number']} "
                f"of {chunk['chunk_count']}"
            )

            passage = (
                chunk_label
                + ":\n"
                + text
            )

            projected_total = (
                total_chars
                + sum(len(item) for item in passages)
                + len(passage)
                + len(group["title"])
                + len(group["url"])
                + len(group["source_type"])
                + 100
            )

            if projected_total > MAX_CONTEXT_CHARS:
                break

            passages.append(passage)

        if not passages:
            continue

        block = (
            f"SOURCE [{source_number}]\n"
            f"Title: {group['title']}\n"
            f"URL: {group['url']}\n"
            f"Source type: {group['source_type']}\n\n"
            + "\n\n".join(passages)
        )

        if total_chars + len(block) > MAX_CONTEXT_CHARS:
            remaining = MAX_CONTEXT_CHARS - total_chars

            if remaining < 300:
                break

            block = block[:remaining]

        blocks.append(block)
        total_chars += len(block)

        if total_chars >= MAX_CONTEXT_CHARS:
            break

    return "\n\n---\n\n".join(blocks)


# -------------------------------------------------------------------
# Limited conversational memory
# -------------------------------------------------------------------


def get_recent_conversation(history):
    """
    Return only the most recent conversation turns.

    Memory is session-based and deliberately short-lived. It is used to
    interpret follow-up questions, not as an evidence source.
    """

    if not history:
        return []

    return history[-MAX_MEMORY_TURNS:]


def format_conversation_context(history):
    """
    Create a compact conversation summary for reference resolution.
    """

    recent = get_recent_conversation(history)

    if not recent:
        return ""

    parts = []

    for index, turn in enumerate(
        recent,
        start=1,
    ):
        answer = (
            turn.get("answer", "")
            [:MAX_MEMORY_ANSWER_CHARS]
        )

        parts.append(
            f"Turn {index}\n"
            f"User: {turn.get('question', '')}\n"
            f"Assistant: {answer}"
        )

    return "\n\n".join(parts)


def resolve_followup_question(
    question,
    history,
):
    """
    Convert a follow-up question into a standalone retrieval query.

    The model may use prior conversation only to resolve references such as
    'that', 'it', 'those findings' or 'the policy implications'. It is
    explicitly forbidden from adding new facts.
    """

    recent = get_recent_conversation(
        history
    )

    if not recent:
        return question

    conversation_context = (
        format_conversation_context(
            recent
        )
    )

    prompt = f"""
You are a query-rewriting component for Ask BIONEXT.

Rewrite the CURRENT QUESTION as a concise, standalone search question using
the previous conversation only to resolve references and omitted context.

Rules:
- Do not answer the question.
- Do not add facts or assumptions.
- Do not introduce information that is absent from the conversation.
- Preserve the user's intent.
- If the current question is already standalone, return it unchanged.
- Return only the rewritten question.

Previous conversation:
{conversation_context}

CURRENT QUESTION:
{question}
"""

    response = client.chat.completions.create(
        model=CONVERSATION_MODEL,
        messages=[
            {
                "role": "user",
                "content": prompt,
            }
        ],
        temperature=0,
        max_tokens=140,
    )

    rewritten = (
        response
        .choices[0]
        .message
        .content
        .strip()
    )

    return rewritten or question


# -------------------------------------------------------------------
# Strong concept evidence checks
# -------------------------------------------------------------------


def has_strong_mcda_evidence(question, retrieved):
    """
    Return True only when an MCDA definition query has retrieved explicit,
    high-confidence BIONEXT Decision Analysis evidence.

    This is intentionally narrow. It does not weaken the general evidence gate;
    it only prevents the gate from rejecting a short acronym/terminology query
    when the correct approved BIONEXT evidence has already been retrieved with
    a strong score.
    """
    if not question or not retrieved:
        return False

    q = question.lower().replace("-", " ")

    asks_about_mcda = (
        re.search(r"\bmcda\b", q) is not None
        or "multi criteria decision analysis" in q
    )

    if not asks_about_mcda:
        return False

    for item in retrieved[:3]:
        if not is_bionext_source(item):
            continue

        title = item["parent_title"].lower().replace("-", " ")
        body = item["text"].lower().replace("-", " ")
        source_text = title + "\n" + body

        contains_mcda = (
            re.search(r"\bmcda\b", source_text) is not None
            or "multi criteria decision analysis" in source_text
        )

        is_decision_analysis_page = (
            "decision-analysis" in item["source_type"].lower()
            or "decision analysis" in title
        )

        strong_score = (
            item.get("retrieval_score", 0.0) >= 0.60
        )

        if (
            contains_mcda
            and is_decision_analysis_page
            and strong_score
        ):
            return True

    return False


def has_strong_case_study_title_evidence(question, retrieved):
    """
    Return True when a short user query clearly identifies an approved BIONEXT
    case study by a distinctive part of its title and that case study has been
    retrieved with a credible score.

    This is intentionally narrow and does not bypass the evidence gate for
    generic topical queries.
    """
    if not question or not retrieved:
        return False

    for item in retrieved[:3]:
        title_bonus = item.get(
            "title_match_bonus",
            case_study_title_match_score(question, item),
        )

        source_type = item["source_type"].lower()
        source_url = (
            item.get("url")
            or item.get("source_url")
            or ""
        ).lower()

        is_case_study_source = (
            "bionext case study" in source_type
            or "/bionext/case-study/" in source_url
        )

        if not is_case_study_source:
            continue

        # Require a clear partial-title match and a credible retrieval score.
        if title_bonus < 0.060:
            continue

        if item.get("retrieval_score", 0.0) < 0.48:
            continue

        return True

    return False


# -------------------------------------------------------------------
# Evidence answerability check
# -------------------------------------------------------------------


def evidence_supports_question(question, groups):
    """
    Check whether the retrieved evidence actually contains enough information
    to answer the user's question without relying on outside knowledge.

    This is deliberately separate from retrieval scoring. Embedding similarity
    can sometimes find superficially related chunks for an unrelated question.
    The evidence gate prevents the answer model from falling back to its own
    general knowledge in those cases.
    """

    if not groups:
        return False

    context = make_context(groups)

    if not context.strip():
        return False

    check_prompt = f"""
You are an evidence-gating system for Ask BIONEXT.

Decide whether the supplied evidence contains enough explicit information to
answer the user's question without using any outside or general knowledge.

Rules:
- Judge only the evidence supplied below.
- Do not answer the question.
- Do not use facts you know from elsewhere.
- If the evidence is only loosely related, tangential, or does not explicitly
  support the requested fact or explanation, return UNSUPPORTED.
- Return SUPPORTED only when a careful answer can be grounded in the evidence.
- Reply with exactly one word: SUPPORTED or UNSUPPORTED.

User question:
{question}

Evidence:
{context}
"""

    response = client.chat.completions.create(
        model=ANSWERABILITY_MODEL,
        messages=[
            {
                "role": "user",
                "content": check_prompt,
            }
        ],
        temperature=0,
        max_tokens=5,
    )

    verdict = (
        response
        .choices[0]
        .message
        .content
        .strip()
        .upper()
    )

    return verdict.startswith("SUPPORTED")


# -------------------------------------------------------------------
# Answer generation
# -------------------------------------------------------------------


def stream_answer(prompt):
    """
    Stream an answer from the OpenAI API.

    Retrieval, evidence gating, source grouping and citations are completed
    before this function is called. Only the final answer-generation step is
    streamed to the Streamlit interface.
    """

    response_stream = client.chat.completions.create(
        model=ANSWER_MODEL,
        messages=[
            {
                "role": "user",
                "content": prompt,
            }
        ],
        temperature=0.15,
        max_tokens=1400,
        stream=True,
    )

    for chunk in response_stream:
        if not chunk.choices:
            continue

        delta = chunk.choices[0].delta
        content = getattr(delta, "content", None)

        if content:
            yield content


def generate_answer(
    question,
    allowed_source_types,
    conversation_history=None,
):
    conversation_history = (
        conversation_history
        or []
    )

    retrieval_question = (
        resolve_followup_question(
            question,
            conversation_history,
        )
    )

    retrieval_question = normalise_retrieval_question(
        retrieval_question
    )

    sources = load_sources()

    retrieved, route = retrieve_sources(
        retrieval_question,
        sources,
        allowed_source_types,
    )

    if not retrieved:
        return (
            "I could not find enough information "
            "in the approved Ask BIONEXT sources "
            "to answer that question.",
            route,
            [],
            [],
        )

    if (
        retrieved[0]["retrieval_score"]
        < MIN_TOP_RETRIEVAL_SCORE
    ):
        return (
            "I could not find sufficiently relevant evidence "
            "in the approved Ask BIONEXT sources to answer "
            "that question reliably.",
            route,
            [],
            retrieved,
        )

    groups = group_retrieved_sources(
        retrieved
    )

    strong_mcda_support = has_strong_mcda_evidence(
        retrieval_question,
        retrieved,
    )

    strong_case_study_title_support = (
        has_strong_case_study_title_evidence(
            retrieval_question,
            retrieved,
        )
    )

    if (
        not strong_mcda_support
        and not strong_case_study_title_support
        and not evidence_supports_question(
            retrieval_question,
            groups,
        )
    ):
        return (
            "I could not find sufficient evidence within the approved "
            "BIONEXT knowledge base to answer that question.",
            route,
            [],
            retrieved,
        )

    context = make_context(
        groups
    )

    conversation_context = (
        format_conversation_context(
            conversation_history
        )
    )

    prompt = f"""
You are Ask BIONEXT 2.0, a source-bounded research assistant for the
EU-funded BIONEXT project.

Your task is to answer the user's question using ONLY the approved source
material supplied below.

Evidence policy:

1. Never use outside knowledge, even if you believe you know the answer.
2. Base every factual claim on the supplied source material.
3. Treat BIONEXT project sources as the primary evidence base.
4. When BIONEXT and external sources cover the same issue, lead with the
   BIONEXT evidence and use external evidence to support, contextualise or
   compare it where useful.
5. IPBES material is authoritative external evidence. Do not present an
   IPBES finding as if it were a BIONEXT finding.
6. If the user explicitly asks what IPBES says, answer primarily from the
   supplied IPBES material, while connecting it to BIONEXT only where the
   supplied BIONEXT sources support that connection.
7. CORDIS should primarily be used for formal project information such as
   objectives, funding and grant details.
8. If the supplied evidence is incomplete, ambiguous or insufficient, do not
   answer from memory or general knowledge. Respond only with:
   "I could not find sufficient evidence within the approved BIONEXT knowledge base to answer that question."
9. If sources disagree, explain the disagreement or difference in framing.

Answer style:

10. Answer the question directly before adding detail.
11. Prefer a concise synthesis over a source-by-source summary.
12. Use plain, professional language suitable for researchers, practitioners
    and policy audiences.
13. Use short headings or bullets only when they genuinely improve clarity.
14. Avoid unnecessary repetition and generic introductory language.
15. Where useful, distinguish clearly between BIONEXT findings, guidance,
    project outputs and external IPBES evidence.

Citations:

16. Cite supporting sources using their square-bracket source numbers,
    for example [1] or [2].
17. Put citations immediately after the statement they support.
18. A statement supported by several sources may cite multiple numbers,
    for example [1][3].
19. Do not invent citation numbers.
20. Do not create a bibliography or a separate "Sources used" section in
    the answer; the application displays the source list automatically.

Conversation policy:

21. The previous conversation below may be used only to understand what the
    user is referring to and to maintain continuity.
22. Previous assistant answers are NOT evidence. Every factual claim in the
    current answer must still be supported by the approved source material.
23. For a follow-up question, answer the user's current request rather than
    unnecessarily repeating the previous answer.

Previous conversation (context only; not evidence):

{conversation_context if conversation_context else "No previous conversation."}

User's current question:

{question}

Standalone interpretation used for retrieval:

{retrieval_question}

Approved source material:

{context}
"""

    answer_stream = stream_answer(
        prompt
    )

    return (
        answer_stream,
        route,
        groups,
        retrieved,
    )


# -------------------------------------------------------------------
# Citation/source alignment
# -------------------------------------------------------------------


def get_cited_source_groups(
    answer,
    groups,
):
    """
    Return only the evidence sources explicitly cited in the generated answer.

    The answer model receives grouped sources numbered [1], [2], etc. This
    helper preserves those original source numbers when displaying and
    exporting the evidence list.

    If a supported answer unexpectedly contains no valid citations, all
    available groups are returned as a transparency fallback.
    """

    if not groups:
        return []

    cited_numbers = []
    seen = set()

    for match in re.finditer(
        r"\[(\d+)\]",
        answer or "",
    ):
        number = int(
            match.group(1)
        )

        if (
            1 <= number <= len(groups)
            and number not in seen
        ):
            seen.add(number)
            cited_numbers.append(number)

    if not cited_numbers:
        cited_numbers = list(
            range(
                1,
                len(groups) + 1,
            )
        )

    cited_groups = []

    for number in cited_numbers:
        group_copy = dict(
            groups[number - 1]
        )

        group_copy[
            "_citation_number"
        ] = number

        cited_groups.append(
            group_copy
        )

    return cited_groups


# -------------------------------------------------------------------
# Answer export
# -------------------------------------------------------------------


def safe_export_filename(question):
    """
    Create a short filesystem-safe filename from the question.
    """

    cleaned = re.sub(
        r"[^A-Za-z0-9]+",
        "-",
        question.strip(),
    ).strip("-").lower()

    if not cleaned:
        cleaned = "answer"

    return cleaned[:60]


def build_markdown_export(
    question,
    answer,
    groups,
):
    """
    Build a portable Markdown export of one Ask BIONEXT answer.
    """

    lines = [
        "# Ask BIONEXT 2.0",
        "",
        "## Question",
        "",
        question.strip(),
        "",
        "## Answer",
        "",
        answer.strip(),
        "",
    ]

    if groups:
        lines.extend(
            [
                "## Evidence sources",
                "",
            ]
        )

        for fallback_number, group in enumerate(
            groups,
            start=1,
        ):
            number = group.get(
                "_citation_number",
                fallback_number,
            )
            title = str(
                group.get(
                    "title",
                    "Untitled source",
                )
            ).strip()

            source_type = (
                humanise_source_type(
                    group.get(
                        "source_type",
                        "",
                    )
                )
            )

            url = str(
                group.get(
                    "url",
                    "",
                )
            ).strip()

            lines.append(
                f"{number}. **{title}**"
            )

            if source_type:
                lines.append(
                    f"   - Source type: {source_type}"
                )

            if url:
                lines.append(
                    f"   - URL: {url}"
                )

            lines.append("")

    lines.extend(
        [
            "---",
            "",
            (
                "Generated by Ask BIONEXT 2.0 from the approved "
                "BIONEXT evidence base. Source links are provided "
                "for verification."
            ),
        ]
    )

    return "\n".join(lines)


def markdown_to_export_lines(markdown_text):
    """
    Convert the limited Markdown used in answers into readable plain-text
    lines for the Word export while preserving headings and list structure.
    """

    export_lines = []

    for raw_line in markdown_text.splitlines():
        line = raw_line.rstrip()

        if not line:
            export_lines.append(
                {
                    "text": "",
                    "kind": "blank",
                }
            )
            continue

        heading_match = re.match(
            r"^(#{1,6})\s+(.*)$",
            line,
        )

        if heading_match:
            export_lines.append(
                {
                    "text": heading_match.group(2),
                    "kind": "heading",
                }
            )
            continue

        bullet_match = re.match(
            r"^\s*[-*]\s+(.*)$",
            line,
        )

        if bullet_match:
            line = (
                "• "
                + bullet_match.group(1)
            )

        # Remove common inline Markdown while keeping the visible text.
        line = re.sub(
            r"\*\*(.*?)\*\*",
            r"\1",
            line,
        )
        line = re.sub(
            r"__(.*?)__",
            r"\1",
            line,
        )
        line = re.sub(
            r"`([^`]*)`",
            r"\1",
            line,
        )
        line = re.sub(
            r"\[([^\]]+)\]\(([^)]+)\)",
            r"\1 (\2)",
            line,
        )

        export_lines.append(
            {
                "text": line,
                "kind": "body",
            }
        )

    return export_lines


def docx_run_xml(
    text_value,
    bold=False,
    size=22,
):
    """
    Create a WordprocessingML run.
    """

    text_value = str(
        text_value
    )

    preserve = (
        ' xml:space="preserve"'
        if (
            text_value.startswith(" ")
            or text_value.endswith(" ")
        )
        else ""
    )

    run_properties = (
        "<w:rPr>"
        + (
            "<w:b/>"
            if bold
            else ""
        )
        + f'<w:sz w:val="{size}"/>'
        + f'<w:szCs w:val="{size}"/>'
        + "</w:rPr>"
    )

    return (
        "<w:r>"
        f"{run_properties}"
        f"<w:t{preserve}>"
        f"{xml_escape(text_value)}"
        "</w:t>"
        "</w:r>"
    )


def docx_paragraph_xml(
    text_value="",
    bold=False,
    size=22,
    space_after=100,
):
    """
    Create a simple WordprocessingML paragraph.
    """

    return (
        "<w:p>"
        "<w:pPr>"
        f'<w:spacing w:after="{space_after}"/>'
        "</w:pPr>"
        + docx_run_xml(
            text_value,
            bold=bold,
            size=size,
        )
        + "</w:p>"
    )


def build_docx_export(
    question,
    answer,
    groups,
):
    """
    Build a dependency-free .docx file containing one answer and its sources.

    The document is created directly as Office Open XML so the deployed app
    does not require an additional Python package solely for export.
    """

    paragraphs = []

    paragraphs.append(
        docx_paragraph_xml(
            "Ask BIONEXT 2.0",
            bold=True,
            size=34,
            space_after=80,
        )
    )

    paragraphs.append(
        docx_paragraph_xml(
            "Exported answer",
            bold=True,
            size=24,
            space_after=220,
        )
    )

    paragraphs.append(
        docx_paragraph_xml(
            "Question",
            bold=True,
            size=24,
            space_after=80,
        )
    )

    paragraphs.append(
        docx_paragraph_xml(
            question.strip(),
            size=22,
            space_after=220,
        )
    )

    paragraphs.append(
        docx_paragraph_xml(
            "Answer",
            bold=True,
            size=24,
            space_after=80,
        )
    )

    for item in markdown_to_export_lines(
        answer
    ):
        if item["kind"] == "heading":
            paragraphs.append(
                docx_paragraph_xml(
                    item["text"],
                    bold=True,
                    size=24,
                    space_after=100,
                )
            )

        elif item["kind"] == "blank":
            paragraphs.append(
                docx_paragraph_xml(
                    "",
                    size=22,
                    space_after=60,
                )
            )

        else:
            paragraphs.append(
                docx_paragraph_xml(
                    item["text"],
                    size=22,
                    space_after=90,
                )
            )

    if groups:
        paragraphs.append(
            docx_paragraph_xml(
                "Evidence sources",
                bold=True,
                size=24,
                space_after=100,
            )
        )

        for fallback_number, group in enumerate(
            groups,
            start=1,
        ):
            number = group.get(
                "_citation_number",
                fallback_number,
            )
            title = str(
                group.get(
                    "title",
                    "Untitled source",
                )
            ).strip()

            source_type = (
                humanise_source_type(
                    group.get(
                        "source_type",
                        "",
                    )
                )
            )

            url = str(
                group.get(
                    "url",
                    "",
                )
            ).strip()

            paragraphs.append(
                docx_paragraph_xml(
                    f"[{number}] {title}",
                    bold=True,
                    size=21,
                    space_after=40,
                )
            )

            if source_type:
                paragraphs.append(
                    docx_paragraph_xml(
                        f"Source type: {source_type}",
                        size=19,
                        space_after=30,
                    )
                )

            if url:
                paragraphs.append(
                    docx_paragraph_xml(
                        f"URL: {url}",
                        size=19,
                        space_after=110,
                    )
                )

    paragraphs.append(
        docx_paragraph_xml(
            (
                "Generated by Ask BIONEXT 2.0 from the approved "
                "BIONEXT evidence base. Source links are provided "
                "for verification."
            ),
            size=18,
            space_after=40,
        )
    )

    document_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<w:document '
        'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
        "<w:body>"
        + "".join(paragraphs)
        + (
            "<w:sectPr>"
            '<w:pgSz w:w="11906" w:h="16838"/>'
            '<w:pgMar w:top="1440" w:right="1440" '
            'w:bottom="1440" w:left="1440" '
            'w:header="708" w:footer="708" w:gutter="0"/>'
            "</w:sectPr>"
        )
        + "</w:body>"
        "</w:document>"
    )

    content_types_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="rels" '
        'ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        '<Default Extension="xml" ContentType="application/xml"/>'
        '<Override PartName="/word/document.xml" '
        'ContentType="application/vnd.openxmlformats-officedocument.'
        'wordprocessingml.document.main+xml"/>'
        "</Types>"
    )

    package_relationships_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships '
        'xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/'
        'relationships/officeDocument" '
        'Target="word/document.xml"/>'
        "</Relationships>"
    )

    output = io.BytesIO()

    with zipfile.ZipFile(
        output,
        "w",
        compression=zipfile.ZIP_DEFLATED,
    ) as docx_zip:
        docx_zip.writestr(
            "[Content_Types].xml",
            content_types_xml,
        )
        docx_zip.writestr(
            "_rels/.rels",
            package_relationships_xml,
        )
        docx_zip.writestr(
            "word/document.xml",
            document_xml,
        )

    output.seek(0)

    return output.getvalue()


def render_export_buttons(
    question,
    answer,
    groups,
    key_prefix,
):
    """
    Render Word and Markdown downloads for one supported answer.
    """

    if (
        not answer
        or answer.startswith(
            "I could not find sufficient evidence"
        )
    ):
        return

    base_name = (
        "ask-bionext-"
        + safe_export_filename(
            question
        )
    )

    markdown_data = (
        build_markdown_export(
            question,
            answer,
            groups,
        )
    )

    docx_data = (
        build_docx_export(
            question,
            answer,
            groups,
        )
    )

    st.markdown(
        '<div class="export-label">Export this answer</div>',
        unsafe_allow_html=True,
    )

    st.markdown(
        """
        <div class="export-note">
          Downloads include the question, answer and evidence-source list.
        </div>
        """,
        unsafe_allow_html=True,
    )

    export_columns = st.columns(2)

    with export_columns[0]:
        st.download_button(
            "Download Word (.docx)",
            data=docx_data,
            file_name=(
                base_name
                + ".docx"
            ),
            mime=(
                "application/vnd.openxmlformats-officedocument."
                "wordprocessingml.document"
            ),
            key=(
                key_prefix
                + "_docx"
            ),
            use_container_width=True,
        )

    with export_columns[1]:
        st.download_button(
            "Download Markdown (.md)",
            data=markdown_data.encode(
                "utf-8"
            ),
            file_name=(
                base_name
                + ".md"
            ),
            mime="text/markdown",
            key=(
                key_prefix
                + "_md"
            ),
            use_container_width=True,
        )


