def set_example_question(example):
    st.session_state["question_input"] = example


def clear_conversation():
    st.session_state["conversation_history"] = []
    st.session_state["question_input"] = ""


def classify_source(group):
    """
    Return a short provenance label and styling class for a grouped source.
    """

    source_type = (
        group.get(
            "source_type",
            "",
        )
        or ""
    )

    source_type_lower = (
        source_type.lower()
    )

    if "bionext" in source_type_lower:
        return (
            "BIONEXT",
            "bionext",
        )

    if "ipbes" in source_type_lower:
        return (
            "IPBES",
            "external",
        )

    if "cordis" in source_type_lower:
        return (
            "CORDIS",
            "external",
        )

    return (
        "External",
        "external",
    )


def humanise_source_type(source_type):
    """
    Keep source-type labels concise and readable in the evidence list.
    """

    if not source_type:
        return "Source"

    cleaned = (
        str(source_type)
        .replace("_", " ")
        .strip()
    )

    return cleaned


def source_domain(url):
    try:
        domain = (
            urlparse(url)
            .netloc
            .lower()
        )

        if domain.startswith("www."):
            domain = domain[4:]

        return domain or "source link"

    except Exception:
        return "source link"


def render_source_cards(groups):
    for fallback_number, group in enumerate(
        groups,
        start=1,
    ):
        number = group.get(
            "_citation_number",
            fallback_number,
        )
        provenance, badge_class = (
            classify_source(
                group
            )
        )

        title = html.escape(
            str(
                group.get(
                    "title",
                    "Untitled source",
                )
            )
        )

        url = html.escape(
            str(
                group.get(
                    "url",
                    "",
                )
            ),
            quote=True,
        )

        source_type = html.escape(
            humanise_source_type(
                group.get(
                    "source_type",
                    "",
                )
            )
        )

        domain = html.escape(
            source_domain(
                group.get(
                    "url",
                    "",
                )
            )
        )

        st.markdown(
            f"""
            <div class="source-card">
              <div class="source-row">
                <span class="source-num">[{number}]</span>
                <div class="source-main">
                  <div class="source-title">
                    <a href="{url}" target="_blank" rel="noopener noreferrer">
                      {title}
                    </a>
                  </div>
                  <div class="source-meta">
                    <span class="source-badge {badge_class}">
                      {provenance}
                    </span>
                    <span>{source_type}</span>
                    <span class="source-domain">{domain}</span>
                    <a
                      class="source-open"
                      href="{url}"
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      Open source ↗
                    </a>
                  </div>
                </div>
              </div>
            </div>
            """,
            unsafe_allow_html=True,
        )


def render_conversation_history(history):
    if not history:
        return

    st.markdown("### Conversation")

    for turn in history:
        st.markdown(
            f"**You:** {turn.get('question', '')}"
        )

        with st.container(
            border=True,
        ):
            st.markdown(
                turn.get(
                    "answer",
                    "",
                )
            )

        groups = turn.get(
            "groups",
            [],
        )

        if groups:
            with st.expander(
                f"Evidence sources ({len(groups)})",
                expanded=False,
            ):
                st.markdown(
                    """
                    <div class="source-list-intro">
                      Citation numbers in the answer correspond to the sources
                      below. BIONEXT and external evidence are labelled
                      separately.
                    </div>
                    """,
                    unsafe_allow_html=True,
                )

                render_source_cards(
                    groups
                )

        render_export_buttons(
            turn.get(
                "question",
                "",
            ),
            turn.get(
                "answer",
                "",
            ),
            groups,
            key_prefix=(
                "history_export_"
                + str(
                    abs(
                        hash(
                            (
                                turn.get(
                                    "question",
                                    "",
                                ),
                                turn.get(
                                    "answer",
                                    "",
                                )[:200],
                            )
                        )
                    )
                )
            ),
        )


