render_brand_header()

if "conversation_history" not in st.session_state:
    st.session_state["conversation_history"] = []

sources = load_sources()

source_types = sorted(
    {
        source["source_type"]
        for source in sources
    }
)

document_keys = {
    (
        source["parent_title"],
        source["url"],
    )
    for source in sources
}


with st.sidebar:
    st.markdown(
        f"""
        <img
          class="sidebar-logo"
          src="data:image/png;base64,{BIONEXT_LOGO_B64}"
          alt="BIONEXT"
        />
        """,
        unsafe_allow_html=True,
    )

    st.write(
        "Ask questions across BIONEXT webpages, resources, linked PDFs "
        "and selected external evidence."
    )

    if sources:
        st.markdown(
            f"""
            <div class="sidebar-stat">
              <div class="sidebar-stat-icon">▤</div>
              <div>
                <strong>{len(document_keys)} documents</strong><br/>
                {len(sources)} retrieval chunks available
              </div>
            </div>
            """,
            unsafe_allow_html=True,
        )
    else:
        st.error(
            "sources.json could not be loaded."
        )

    with st.expander(
        "Advanced search options",
        expanded=False,
    ):
        selected_source_types = st.multiselect(
            "Search within",
            options=source_types,
            default=source_types,
        )

        show_technical_details = st.checkbox(
            "Show technical retrieval details",
            value=False,
        )

        st.caption(
            "BIONEXT sources receive a modest priority in retrieval. "
            "Deselect a source type to exclude it."
        )

    if st.session_state["conversation_history"]:
        st.button(
            "Clear conversation",
            key="clear_conversation_button",
            use_container_width=True,
            on_click=clear_conversation,
        )

    st.caption(
        "Ask BIONEXT answers only from the approved evidence base. "
        "Unsupported questions are not answered from general knowledge."
    )

    st.markdown(
        """
        <div class="help-box">
          <strong>ⓘ Need help?</strong><br/><br/>
          If you have suggestions or find an issue, please contact
          <a href="mailto:support@oppla.eu">support@oppla.eu</a>.
        </div>
        """,
        unsafe_allow_html=True,
    )


st.markdown(
    """
    <div class="intro-copy">
      Ask a question about BIONEXT. The app searches the approved knowledge
      base and synthesises the most relevant evidence, with links to the
      sources used.
    </div>
    """,
    unsafe_allow_html=True,
)


render_conversation_history(
    st.session_state[
        "conversation_history"
    ]
)

if not st.session_state[
    "conversation_history"
]:
    st.markdown(
        '<div class="example-label">Try an example</div>',
        unsafe_allow_html=True,
    )

    example_questions = [
        "What are the main objectives of the BIONEXT project?",
        "What does BIONEXT say about justice in biodiversity policy?",
        "How does BIONEXT use decision analysis to support environmental decision-making?",
        "What is transformative change according to the IPBES Transformative Change Assessment?",
    ]

    example_cols = st.columns(2)

    for index, example in enumerate(
        example_questions
    ):
        with example_cols[index % 2]:
            st.button(
                example,
                key=f"example_{index}",
                use_container_width=True,
                on_click=set_example_question,
                args=(example,),
            )


question = st.text_input(
    "Question",
    key="question_input",
    placeholder=(
        "Type your question about BIONEXT here..."
    ),
)


if (
    st.button(
        "Ask BIONEXT",
        type="primary",
    )
    and question.strip()
):
    if not get_api_key():
        st.error(
            "No OpenAI API key found. "
            "Add OPENAI_API_KEY in Streamlit Secrets."
        )

    elif not selected_source_types:
        st.warning(
            "Please select at least one source type."
        )

    else:
        with st.spinner(
            "Searching the BIONEXT evidence base..."
        ):
            try:
                (
                    answer,
                    route,
                    groups,
                    retrieved,
                ) = generate_answer(
                    question,
                    selected_source_types,
                    st.session_state[
                        "conversation_history"
                    ],
                )

                unsupported = (
                    isinstance(
                        answer,
                        str,
                    )
                    and answer.startswith(
                        "I could not find"
                    )
                )

                if unsupported:
                    final_answer = answer
                    st.info(
                        final_answer
                    )
                else:
                    with st.container(
                        border=True,
                    ):
                        answer_placeholder = st.empty()
                        streamed_answer = ""

                        for answer_chunk in answer:
                            streamed_answer += answer_chunk

                            answer_placeholder.markdown(
                                streamed_answer + " ▌"
                            )

                        answer_placeholder.markdown(
                            streamed_answer
                        )

                    final_answer = streamed_answer

                cited_groups = (
                    get_cited_source_groups(
                        final_answer,
                        groups,
                    )
                    if not unsupported
                    else []
                )

                if cited_groups:
                    st.markdown(
                        "### Evidence sources"
                    )

                    st.markdown(
                        f"""
                        <div class="source-list-intro">
                          The answer above cites {len(cited_groups)} source{
                              "" if len(cited_groups) == 1 else "s"
                          } from the approved evidence base. Citation numbers
                          correspond directly to the entries below.
                        </div>
                        """,
                        unsafe_allow_html=True,
                    )

                    render_source_cards(
                        cited_groups
                    )

                render_export_buttons(
                    question,
                    final_answer,
                    cited_groups,
                    key_prefix=(
                        "current_export_"
                        + str(
                            len(
                                st.session_state[
                                    "conversation_history"
                                ]
                            )
                        )
                    ),
                )

                st.session_state[
                    "conversation_history"
                ].append(
                    {
                        "question": question,
                        "answer": final_answer,
                        "groups": cited_groups,
                    }
                )

                st.session_state[
                    "conversation_history"
                ] = st.session_state[
                    "conversation_history"
                ][-MAX_MEMORY_TURNS:]

                if show_technical_details:
                    with st.expander(
                        "Technical retrieval details",
                        expanded=False,
                    ):
                        st.caption(
                            f"Search route: {route}"
                        )

                        if has_strong_mcda_evidence(
                            question,
                            retrieved,
                        ):
                            st.caption(
                                "Strong MCDA evidence override: active"
                            )

                        if has_strong_case_study_title_evidence(
                            question,
                            retrieved,
                        ):
                            st.caption(
                                "Strong case-study title match: active"
                            )

                        for item in retrieved:
                            st.write(
                                f"**{item['title']}**"
                            )

                            st.caption(
                                f"{item['source_type']} · "
                                f"semantic {item['semantic_score']:.3f} · "
                                f"keyword {item['keyword_score']:.3f} · "
                                f"priority +{item['priority_bonus']:.3f} · "
                                f"concept +{item.get('concept_bonus', 0.0):.3f} · "
                                f"title +{item.get('title_match_bonus', 0.0):.3f} · "
                                f"combined {item['retrieval_score']:.3f}"
                            )

            except Exception as exc:
                st.error(
                    f"Something went wrong: {exc}"
                )


render_partner_footer()
